void handle_vm_cmdTell(GameClient& cl, const uint8_t* body, size_t len)
{
    size_t off = 0;
    if (off + 1 > len) return;
    uint8_t nameLen = body[off++];
    if (off + nameLen > len) return;
    auto name = make_string(body + off, nameLen);
    off += nameLen;
    if (off + 1 > len) return;
    uint8_t msgLen = body[off++];
